<?php
require_once __DIR__.'/legacy_operational_read.php';
function lop_savings_report_rows(mysqli $db,string $start,string $end,array $f): array {
    if(!lop_ready($db))return [];$rows=[];
    foreach(lf_rows($db,"SELECT j.*,(SELECT MIN(a.actor_id) FROM legacy_op_audit a WHERE a.unit_id=j.unit_id AND a.entity_type='bank_new' AND a.entity_id=j.id) native_actor,o.name,o.source_identity,o.source_class,s.NO_INDUK,s.NO_induk_diknas,s.master_kelas_id FROM legacy_op_journals j JOIN legacy_op_owners o ON o.id=j.owner_id AND o.unit_id=j.unit_id LEFT JOIN siswa s ON s.id=o.student_id AND s.unit_id=o.unit_id JOIN legacy_full_batches b ON b.id=j.batch_id AND b.unit_id=j.unit_id WHERE b.state='completed' AND j.cancelled=0 AND j.source_date>=? AND j.source_date<? ORDER BY j.source_date,j.id",[$start,$end]) as $j){
        $operator=$j['origin']==='adjustment'?'':($j['origin']==='legacy'?lful_operator_key((int)$j['unit_id'],$j['source_operator']):(string)$j['source_operator']);
        $operatorKey=$j['origin']==='legacy'?$operator:(string)($j['native_actor']??$operator);if(($f['operator']??'')!==''&&$f['operator']!==$operatorKey)continue;if(isset($f['_multi']['operator'])&&!filter_is_all($f['_multi']['operator'])&&!in_array($operatorKey,$f['_multi']['operator'],true))continue;
        $rows[]=['id'=>-(1000000000+(int)$j['id']),'unit_id'=>$j['unit_id'],'NO_INDUK'=>$j['NO_INDUK']??'rekening:'.$j['owner_id'],'NAMA'=>$j['name'],'NO_induk_diknas'=>$j['NO_induk_diknas']??'','master_kelas_id'=>$j['master_kelas_id'],'kelas_label'=>$j['source_class'],'tingkat'=>null,'kode_rombel'=>null,'is_placeholder'=>0,'tanggal'=>$j['source_date'],'masuk'=>$j['origin']==='adjustment'?'0.00':$j['incoming'],'keluar'=>$j['origin']==='adjustment'?'0.00':$j['outgoing'],'user_id'=>$operator,'keterangan'=>$j['origin']==='adjustment'?'Penyesuaian Saldo Migrasi':($j['origin']==='legacy'?'Legacy · '.$j['note']:$j['note']),'jenis'=>$j['origin']==='adjustment'?'Penyesuaian Saldo Migrasi':(lf_cents($j['incoming'])>0?'Masuk':'Keluar'),'urutan_mutasi'=>lf_cents($j['incoming'])>0?0:1,'delta_opening'=>$j['origin']==='adjustment'?(float)$j['incoming']-(float)$j['outgoing']:0,'legacy_origin'=>$j['origin']];
    }return $rows;
}
function lop_savings_report_openings(mysqli $db,array $identities,string $before): array {
    if(!lop_ready($db))return [];$out=[];
    foreach(lf_rows($db,"SELECT COALESCE(s.NO_INDUK,CONCAT('rekening:',o.id)) identity_key,SUM(j.incoming-j.outgoing) amount FROM legacy_op_journals j JOIN legacy_op_owners o ON o.id=j.owner_id AND o.unit_id=j.unit_id LEFT JOIN siswa s ON s.id=o.student_id AND s.unit_id=o.unit_id JOIN legacy_full_batches b ON b.id=j.batch_id AND b.unit_id=j.unit_id WHERE b.state='completed' AND j.cancelled=0 AND j.source_date<? GROUP BY identity_key",[$before]) as $r)if(in_array($r['identity_key'],$identities,true))$out[$r['identity_key']]=(float)$r['amount'];return $out;
}
